410:     const map = {
411:       powerplant: 112, watertower: 78, solar: 46, police: 54, fire: 60, school: 86, hospital: 96,
412:       smallpark: 54, park: 74, plaza: 64, fountain: 58, ferris: 126, stadium: 100, monument: 96,
413:       tree: 58, flowers: 44, streetlamp: 54, rock: 36, lot_r: 34, lot_c: 34, lot_i: 34
