549:   function drawGhost(ctx, ghost, time) {
550:     const { def, x, y, valid } = ghost;
551:     const b = { defId: def.id, x, y, w: def.w, h: def.h, level: def.previewLevel || 1, uid: 1 };
552:     ctx.save();
553:     ctx.globalAlpha = .68;
554:     drawObject(ctx, b, time);
555:     ctx.globalAlpha = 1;
556:     const pts = diamondPoints(x, y, def.w, def.h, .02);
557:     poly(ctx, pts, valid ? 'rgba(80,220,130,.16)' : 'rgba(255,90,60,.2)', valid ? '#4ee58a' : '#ff5b3d', 2);
558:     if (def.radius) {
