188:     const trees = [];
189:     for (let y = 0; y < GRID; y++) for (let x = 0; x < GRID; x++) {
190:       const t = grid[idx(x, y)];
191:       if (t.terrain !== 'grass') continue;
192:       const dc = Math.hypot(x - 12, y - 12);
193:       const edge = Math.min(x, y, GRID - 1 - x, GRID - 1 - y);
194:       let chance = 0;
195:       if (dc > 7.6) chance = .22;
196:       if (edge < 3) chance += .2;
197:       if (dc > 10) chance += .12;
198:       if (rand() < chance) trees.push({ defId: 'tree', x, y, level: 1, variant: Math.floor(rand() * 3) });
199:       else if (rand() < .018 && dc > 6.5) trees.push({ defId: 'rock', x, y, level: 1 });
200:     }
201:     return { grid, treeSeed: trees };
202:   }
