204:   function newGame(name) {
205:     const seed = (Date.now() ^ (Math.random() * 1e9)) >>> 0;
206:     state = blankState(name);
207:     const map = generateMap(seed);
208:     state.grid = map.grid;
209:     // place initial nature as buildings
210:     for (const t of map.treeSeed) addBuilding(t.defId, t.x, t.y, 1, { free: true, variant: t.variant });
211:     // force nature on reserved zone tiles too
212:     cam.x = 0; cam.y = GRID * 16 - 10;
213:     cam.zoom = defaultZoom();
214:     state.cars = [];
215:     spawnCars(true);
216:     recalc();
217:     checkUnlocks(true);
218:     updateAll();
219:     saveGame(true);
220:   }
