227:   function addBuilding(defId, x, y, level, opt) {
228:     const def = DEFS[defId]; if (!def) return null;
229:     opt = opt || {};
230:     const b = {
231:       uid: uid(), defId, x, y, w: def.w, h: def.h, level: level || 0,
232:       growth: 0, evo: 0, variant: opt.variant != null ? opt.variant : Math.floor(Math.random() * 6)
233:     };
234:     for (let yy = y; yy < y + def.h; yy++) for (let xx = x; xx < x + def.w; xx++) {
235:       if (!inBounds(xx, yy)) return null;
236:       const t = state.grid[idx(xx, yy)];
237:       t.b = b;
238:     }
239:     state.buildings.push(b);
240:     if (!opt.free) state.money -= def.cost;
241:     return b;
242:   }
243:   function removeBuilding(b, refund) {
244:     if (!b) return;
245:     for (let yy = b.y; yy < b.y + b.h; yy++) for (let xx = b.x; xx < b.x + b.w; xx++) {
246:       if (inBounds(xx, yy) && state.grid[idx(xx, yy)].b === b) state.grid[idx(xx, yy)].b = null;
247:     }
248:     const i = state.buildings.indexOf(b);
249:     if (i >= 0) state.buildings.splice(i, 1);
250:     if (refund) state.money += Math.round(defOf(b).cost * .35);
251:     if (state.selected && state.selected.uid === b.uid) { state.selected = null; hideSelection(); }
252:   }
253:   function roadAccess(b) {
254:     for (let y = b.y; y < b.y + b.h; y++) for (let x = b.x; x < b.x + b.w; x++) {
255:       if (inBounds(x - 1, y) && state.grid[idx(x - 1, y)].road) return true;
256:       if (inBounds(x + 1, y) && state.grid[idx(x + 1, y)].road) return true;
257:       if (inBounds(x, y - 1) && state.grid[idx(x, y - 1)].road) return true;
258:       if (inBounds(x, y + 1) && state.grid[idx(x, y + 1)].road) return true;
259:     }
260:     return false;
261:   }
262:   function canPlace(def, x, y, opts) {
263:     opts = opts || {};
264:     if (!def) return { ok: false, msg: 'Bangunan tidak dikenal.' };
265:     if (x < 0 || y < 0 || x + def.w > state.gridSize || y + def.h > state.gridSize) return { ok: false, msg: 'Di luar batas kota.' };
266:     let wild = false;
267:     for (let yy = y; yy < y + def.h; yy++) for (let xx = x; xx < x + def.w; xx++) {
268:       const t = state.grid[idx(xx, yy)];
269:       if (t.terrain === 'water') return { ok: false, msg: 'Tidak bisa membangun di atas air.' };
270:       if (t.road) return { ok: false, msg: 'Petak sudah dipakai jalan.' };
271:       if (t.b) {
272:         if (def.kind === 'road') return { ok: false, msg: 'Ada bangunan di petak ini.' };
273:         if (t.b.defId === 'tree' || t.b.defId === 'rock') wild = true;
274:         else return { ok: false, msg: 'Petak sudah terisi.' };
275:       }
276:     }
277:     if (wild) return { ok: false, msg: 'Bersihkan pohon/batu dengan alat bongkar dulu.' };
278:     if (def.kind !== 'road' && def.kind !== 'decor') {
279:       let ok = false;
280:       const test = { x, y, w: def.w, h: def.h };
281:       ok = roadAccess(test);
282:       if (!ok) return { ok: false, msg: 'Butuh akses jalan di sebelahnya.' };
283:     }
284:     if (!opts.free && state.money < def.cost) return { ok: false, msg: 'Kas kota tidak cukup.' };
285:     return { ok: true };
286:   }
287:   function placeAt(defId, x, y) {
288:     const def = DEFS[defId];
289:     const chk = canPlace(def, x, y);
290:     if (!chk.ok) { sfx.error(); toast(chk.msg, 'bad', 'info'); return false; }
291:     if (def.kind === 'road') {
292:       const t = state.grid[idx(x, y)];
293:       t.road = true; state.money -= def.cost;
294:       ensureCars();
295:     } else {
296:       addBuilding(defId, x, y, 0);
297:     }
298:     sfx.place();
299:     recalc(); checkUnlocks(); updateHUD(true); renderCatalog();
300:     saveGame(true);
301:     return true;
302:   }
303:   function forcePlace(defId, x, y, level) {
304:     const def = DEFS[defId]; if (!def) return null;
305:     if (def.kind === 'road') {
306:       for (let yy = y; yy < y + def.h; yy++) for (let xx = x; xx < x + def.w; xx++) {
307:         if (inBounds(xx, yy)) {
308:           const t = state.grid[idx(xx, yy)];
309:           if (t.b && !t.b.defId !== 'tree') removeBuilding(t.b, false);
310:           t.b = null; t.road = true;
311:         }
312:       }
313:       return true;
314:     }
315:     for (let yy = y; yy < y + def.h; yy++) for (let xx = x; xx < x + def.w; xx++) {
316:       if (inBounds(xx, yy)) {
317:         const t = state.grid[idx(xx, yy)];
318:         if (t.b) removeBuilding(t.b, false);
319:         t.road = false; t.b = null;
320:       }
321:     }
322:     return addBuilding(defId, x, y, level == null ? 1 : level, { free: true });
323:   }
324:   function bulldozeAt(x, y) {
325:     const t = tileAt(x, y);
326:     if (!t) return;
327:     if (t.b) {
328:       const b = t.b;
329:       const def = defOf(b);
330:       if (def.maint === 0 && def.cost === 0 && b.defId === 'rock') { removeBuilding(b, false); toast('Batu dibersihkan.', 'good', 'check'); }
331:       else {
332:         removeBuilding(b, true);
333:         toast(`${def.name} dibongkar · +${money(Math.round(def.cost * .35))}`, 'info', 'trash');
334:       }
335:       sfx.demolish();
336:     } else if (t.road) {
337:       t.road = false; state.money += Math.round(DEFS.road.cost * .5);
338:       toast('Jalan dibongkar.', 'info', 'trash');
339:       sfx.demolish();
340:     } else { return; }
341:     state.cars = state.cars.filter(c => tileAt(Math.round(c.x), Math.round(c.y))?.road);
342:     recalc(); checkUnlocks(); updateHUD(true); updateSelection(); saveGame(true);
343:   }
