441:   function recalc() {
442:     if (!state) return;
443:     let pop = 0, workers = 0, jobs = 0, cJobs = 0, iJobs = 0;
444:     let powerUse = 0, powerCap = 0, waterUse = 0, waterCap = 0, expense = 0;
445:     let roadCount = 0, zoneCount = 0, houses = 0, shops = 0, factories = 0;
446:     let hasPower = false, hasWater = false, hasPark = false, hasSchool = false, hasStadium = false;
447:     const houseList = [], amenities = [], polluters = [];
448:     for (const b of state.buildings) {
449:       const d = defOf(b); if (!d) continue;
450:       expense += d.maint || 0;
451:       if (d.kind === 'zone-r') {
452:         zoneCount++;
453:         if (b.level > 0) {
454:           pop += levelVal(d, 'cap', b.level);
455:           powerUse += levelVal(d, 'powerUse', b.level);
456:           waterUse += levelVal(d, 'waterUse', b.level);
457:           houseList.push(b); houses++;
458:         }
459:       } else if (d.kind === 'zone-c') {
460:         zoneCount++;
461:         if (b.level > 0) {
462:           cJobs += levelVal(d, 'jobs', b.level);
463:           powerUse += levelVal(d, 'powerUse', b.level);
464:           waterUse += levelVal(d, 'waterUse', b.level);
465:           shops++;
466:         }
467:       } else if (d.kind === 'zone-i') {
468:         zoneCount++;
469:         if (b.level > 0) {
470:           iJobs += levelVal(d, 'jobs', b.level);
471:           powerUse += levelVal(d, 'powerUse', b.level);
472:           waterUse += levelVal(d, 'waterUse', b.level);
473:           factories++;
474:           polluters.push(b);
475:         }
476:       } else {
477:         powerUse += d.powerUse || 0;
478:         waterUse += d.waterUse || 0;
479:         powerCap += d.powerSupply || 0;
480:         waterCap += d.waterSupply || 0;
481:         jobs += d.jobs || 0;
482:         if (d.powerSupply) hasPower = true;
483:         if (d.waterSupply) hasWater = true;
484:         if (artOr(defOf(b), b) === 'park' || artOr(defOf(b), b) === 'smallpark') hasPark = true;
485:         if (artOr(defOf(b), b) === 'school') hasSchool = true;
486:         if (artOr(defOf(b), b) === 'stadium') hasStadium = true;
487:       }
488:       if (d.happy && d.radius) amenities.push(b);
489:       if (b.defId === 'solar') hasPower = true;
490:     }
491:     for (let y = 0; y < state.gridSize; y++) for (let x = 0; x < state.gridSize; x++) if (state.grid[idx(x, y)].road) roadCount++;
492:     expense += roadCount * DEFS.road.maint;
493:     for (const pid in state.policies) {
494:       const p = KK.POLICIES.find(x => x.id === pid);
495:       if (p && state.policies[pid]) expense += p.cost;
496:     }
497:     workers = Math.round(pop * .42);
498:     jobs += cJobs + iJobs;
499:     const powered = powerUse <= powerCap;
500:     const watered = waterUse <= waterCap;
501:     const policyHappy = KK.POLICIES.reduce((n, p) => n + (state.policies[p.id] ? p.happiness : 0), 0);
502:     const commerceBonus = KK.POLICIES.reduce((n, p) => n + (state.policies[p.id] ? (p.commerce || 0) : 0), 0);
503:     const taxPenalty = Math.max(0, (state.taxRate || 9) - 10) * 2.5;
504:     const unemployment = workers > jobs ? Math.min(24, (workers - jobs) / Math.max(1, workers) * 30) : 0;
505:     const pollutionPolicy = KK.POLICIES.reduce((n, p) => n + (state.policies[p.id] ? (p.pollution || 0) : 0), 0);
506:     let happyTotal = 0;
507:     for (const h of houseList) {
508:       let bonus = 0;
509:       for (const a of amenities) {
510:         const ad = defOf(a);
511:         if (distance(h, a) <= (ad.radius || 0)) bonus += ad.happy || 0;
512:       }
513:       bonus = Math.min(26, bonus);
514:       let poll = 0;
515:       for (const f of polluters) {
516:         if (distance(h, f) <= (defOf(f).pollutionRadius || 3)) poll += 1.6 + f.level * .5;
517:       }
518:       poll = Math.max(0, Math.min(14, poll) - pollutionPolicy);
519:       let hv = 56 + bonus + policyHappy + state.moodBoost - taxPenalty - unemployment - poll;
520:       if (!powered) hv -= 24;
521:       if (!watered) hv -= 20;
522:       happyTotal += clamp(hv, 0, 100);
523:     }
524:     let happiness;
525:     if (houseList.length) happiness = happyTotal / houseList.length;
526:     else happiness = clamp(62 + policyHappy + state.moodBoost - taxPenalty, 0, 100);
527:     const income = pop * .33 * ((state.taxRate || 9) / 9) + cJobs * .5 * (1 + commerceBonus) + iJobs * .36;
528:     state.population = pop;
529:     state.workers = workers;
530:     state.jobs = jobs;
531:     state.commercialJobs = cJobs;
532:     state.industrialJobs = iJobs;
533:     state.powerUse = Math.round(powerUse * 10) / 10;
534:     state.powerCap = powerCap;
535:     state.waterUse = Math.round(waterUse * 10) / 10;
536:     state.waterCap = waterCap;
537:     state.powered = powered;
538:     state.watered = watered;
539:     state.expense = Math.round(expense * 10) / 10;
540:     state.income = Math.round(income * 10) / 10;
541:     state.net = Math.round((income - expense) * 10) / 10;
542:     state.happiness = Math.round(happiness);
543:     state.roadCount = roadCount;
544:     state.zoneCount = zoneCount;
545:     state.hasPower = hasPower;
546:     state.hasWater = hasWater;
547:     state.hasPark = hasPark;
548:     state.hasSchool = hasSchool;
549:     state.hasStadium = hasStadium;
550:     state.houses = houses; state.shops = shops; state.factories = factories;
551:     state.demandR = clamp(16 + jobs * 1.25 - pop * .38 + (state.happiness < 48 ? -8 : 0), 0, 100);
552:     state.demandC = clamp(8 + pop * .34 - cJobs * .85, 0, 100);
553:     state.demandI = clamp(5 + pop * .18 - iJobs * .45, 0, 100);
554:     state.maxPop = Math.max(state.maxPop, pop);
555:     // economy is deliberately forgiving: never below -2.000
556:     if (state.money < -2000) state.money = -2000;
557:     if (!state.stats) state.stats = {};
558:     state.stats.houses = houses; state.stats.shops = shops; state.stats.factories = factories;
559:   }
560:   function artOr(def, b) { return KK.render.artFor(def, b.level); }
561:   function demandFor(kind) {
562:     return kind === 'r' ? state.demandR : kind === 'c' ? state.demandC : state.demandI;
563:   }
564: 
565:   function simulateTick() {
566:     if (!state) return;
567:     state.tick++;
568:     const scale = periodScale();
569:     state.elapsedDays = (state.elapsedDays || 0) + PERIOD_DAYS[state.period];
570:     state.hour = (state.hour + .36 * scale) % 24;
571:     state.moodBoost *= Math.pow(.966, scale);
572:     if (Math.abs(state.moodBoost) < .05) state.moodBoost = 0;
573:     recalc();
574:     const hasPower = state.powerCap >= state.powerUse;
575:     const hasWater = state.waterCap >= state.waterUse;
576:     let changed = false;
577:     for (const b of state.buildings.slice()) {
578:       const d = defOf(b);
579:       if (!d || !d.kind || !d.kind.startsWith('zone')) continue;
580:       const ok = hasPower && hasWater && roadAccess(b);
581:       if (b.level === 0) {
582:         const kind = zoneArtKind(d);
583:         if (ok && demandFor(kind) > 0 && state.happiness >= 38) {
584:           b.growth += (1 + (state.happiness > 66 ? .5 : 0)) * scale;
585:           if (b.growth >= 2) { b.level = 1; b.growth = 0; b.evo = 0; changed = true; }
586:         } else b.growth = Math.max(0, b.growth - .5 * scale);
587:       } else {
588:         const school = nearbyArt(b, ['school']);
589:         const hospital = nearbyArt(b, ['hospital']);
590:         let maxLv = 3;
591:         if (kindOf(d) === 'r') maxLv = 2 + (school ? 1 : 0) + (hospital ? 1 : 0);
592:         if (b.level < Math.min(d.maxLevel || 3, maxLv) && ok && state.happiness >= 50) {
593:           b.evo += (state.happiness >= 68 ? 2 : 1) * scale;
594:           const need = [0, 7, 13, 21][b.level] || 99;
595:           if (b.evo >= need) { b.level++; b.evo = 0; changed = true; }
596:         } else if (b.evo > 0) b.evo = Math.max(0, b.evo - scale);
597:       }
598:     }
599:     if (changed) recalc();
600:     state.money += (state.income - state.expense) * scale;
601:     // resource warnings
602:     if (!state.warned.power && state.powerUse > state.powerCap && state.powerUse > 0) {
603:       toast('Listrik tidak cukup! Bangun pembangkit atau taman surya.', 'bad', 'bolt');
604:       state.warned.power = true;
605:     }
606:     if (state.powerUse <= state.powerCap) state.warned.power = false;
607:     if (!state.warned.water && state.waterUse > state.waterCap && state.waterUse > 0) {
608:       toast('Pasokan air kurang! Bangun menara air tambahan.', 'bad', 'drop');
609:       state.warned.water = true;
610:     }
611:     if (state.waterUse <= state.waterCap) state.warned.water = false;
612:     checkUnlocks();
613:     checkMissions();
614:     // random city event
615:     state.eventTimer = (state.eventTimer || 48) - scale;
616:     if (state.eventTimer <= 0) {
617:       state.eventTimer = 55 + Math.floor(Math.random() * 25);
618:       if (!state.modalPause && state.population >= 20) setTimeout(showRandomEvent, 350);
619:     }
620:     if (state.tick % Math.max(1, Math.round(2 / scale)) === 0) spawnCars();
621:     if (state.tick % Math.max(1, Math.round(20 / scale)) === 0) saveGame(true);
622:     updateAll();
