    function facesOf(l, w, z0, z1) {
      const defs = [
        { key: 'front', a: [l, w], b: [l, -w] },
        { key: 'back', a: [-l, -w], b: [-l, w] },
        { key: 'sideR', a: [l, -w], b: [-l, -w] },
        { key: 'sideL', a: [-l, w], b: [l, w] }
      ];
      const vis = [];
      for (const f of defs) {
        const a = P(f.a[0], f.a[1], z0), b = P(f.b[0], f.b[1], z0);
        const ex = b.x - a.x, ey = b.y - a.y;
        let nx = ey, ny = -ex;
        const mx = (a.x + b.x) / 2 - p.x, my = (a.y + b.y) / 2 - p.y;
        if (nx * mx + ny * my < 0) { nx = -nx; ny = -ny; }
        const nl = Math.hypot(nx, ny) || 1;
        if (ny / nl < .05) continue;
        vis.push({ key: f.key, a: f.a, b: f.b, a0: a, b0: b, midY: (a.y + b.y) / 2 });
      }
      vis.sort((a, b) => a.midY - b.midY);
      return vis;
    }
    function drawBox(l, w, z0, z1, colors, detail) {
      const vis = facesOf(l, w, z0, z1);
      for (const f of vis) {
        poly(ctx, [f.a0, f.b0, P(f.b[0], f.b[1], z1), P(f.a[0], f.a[1], z1)], colors[f.key] || colors.side, colors.outline, .5);
        if (detail) detail(f, z0, z1);
      }
      poly(ctx, [P(l, w, z1), P(l, -w, z1), P(-l, -w, z1), P(-l, w, z1)], colors.top);
      return vis;
    }
